export function downloadRecoveryPDF(recoveryKey: string): void {
	const escape = (text: string) =>
		text.replace(/\\/g, '\\\\').replace(/\(/g, '\\(').replace(/\)/g, '\\)');
	const segments = recoveryKey.split('-');
	const lines = [
		'This is the ONLY way to recover your data if you lose your password.',
		'Store this recovery key securely. Losing it will result in permanent data loss.',
		'',
		...Array.from({ length: Math.ceil(segments.length / 3) }, (_, index) =>
			segments.slice(index * 3, index * 3 + 3).join('-'),
		),
		'',
		'Generated by Arkive Core setup.',
	];
	const content = [
		'BT',
		'/F1 20 Tf',
		'72 760 Td',
		'(Arkive Core - Vault Recovery Key) Tj',
		'ET',
		...lines.flatMap((line, index) => [
			'BT',
			`/${index < 2 ? 'F1' : 'F2'} ${index < 2 ? 11 : 14} Tf`,
			`72 ${730 - index * 22} Td`,
			`(${escape(line)}) Tj`,
			'ET',
		]),
	].join('\n');
	const objects = [
		'<< /Type /Catalog /Pages 2 0 R >>',
		'<< /Type /Pages /Kids [3 0 R] /Count 1 >>',
		'<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 4 0 R /F2 5 0 R >> >> /Contents 6 0 R >>',
		'<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>',
		'<< /Type /Font /Subtype /Type1 /BaseFont /Courier-Bold >>',
		`<< /Length ${content.length} >>\nstream\n${content}\nendstream`,
	];
	let pdf = '%PDF-1.4\n';
	const offsets = [0];
	objects.forEach((object, index) => {
		offsets.push(pdf.length);
		pdf += `${index + 1} 0 obj\n${object}\nendobj\n`;
	});
	const xrefOffset = pdf.length;
	pdf += `xref\n0 ${objects.length + 1}\n0000000000 65535 f \n`;
	for (const offset of offsets.slice(1)) pdf += `${String(offset).padStart(10, '0')} 00000 n \n`;
	pdf += `trailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\nstartxref\n${xrefOffset}\n%%EOF`;

	const url = URL.createObjectURL(new Blob([pdf], { type: 'application/pdf' }));
	const link = document.createElement('a');
	link.href = url;
	link.download = 'arkive-vault-recovery-key.pdf';
	document.body.appendChild(link);
	link.click();
	link.remove();
	window.setTimeout(() => URL.revokeObjectURL(url), 1000);
}
